    "/** @internal */\012export function arrayUpdate(mutate, at, v, arr) {\012  let out = arr;\012  if (!mutate) {\012    const len = arr.length;\012    out = new Array(len);\012    for (let i = 0; i < len; ++i) out[i] = arr[i];\012  }\012  out[at] = v;\012  return out;\012}\012/** @internal */\012export function arraySpliceOut(mutate, at, arr) {\012  const newLen = arr.length - 1;\012  let i = 0;\012  let g = 0;\012  let out = arr;\012  if (mutate) {\012    i = g = at;\012  } else {\012    out = new Array(newLen);\012    while (i < at) out[g++] = arr[i++];\012  }\012  ++i;\012  while (i <= newLen) out[g++] = arr[i++];\012  if (mutate) {\012    out.length = newLen;\012  }\012  return out;\012}\012/** @internal */\012export function arraySpliceIn(mutate, at, v, arr) {\012  const len = arr.length;\012  if (mutate) {\012    let i = len;\012    while (i >= at) arr[i--] = arr[i];\012    arr[at] = v;\012    return arr;\012  }\012  let i = 0,\012    g = 0;\012  const out = new Array(len + 1);\012  while (i < at) out[g++] = arr[i++];\012  out[at] = v;\012  while (i < len) out[++g] = arr[i++];\012  return out;\012}\012//# sourceMappingURL=array.js.map";
