    "export class SourceValuesIterator {\012    constructor(initialValues, maxInitialIterations, remainingSkips) {\012        this.initialValues = initialValues;\012        this.maxInitialIterations = maxInitialIterations;\012        this.remainingSkips = remainingSkips;\012    }\012    [Symbol.iterator]() {\012        return this;\012    }\012    next() {\012        if (--this.maxInitialIterations !== -1 && this.remainingSkips >= 0) {\012            const n = this.initialValues.next();\012            if (!n.done)\012                return { value: n.value, done: false };\012        }\012        return { value: undefined, done: true };\012    }\012    skippedOne() {\012        --this.remainingSkips;\012        ++this.maxInitialIterations;\012    }\012}\012";
