    "import { skipN } from 'pure-rand';\012import { Random } from '../../random/generator/Random.js';\012import { Value } from '../arbitrary/definition/Value.js';\012import { safeMap } from '../../utils/globals.js';\012function tossNext(generator, rng, index) {\012    rng.unsafeJump();\012    return generator.generate(new Random(rng), index);\012}\012export function* toss(generator, seed, random, examples) {\012    for (let idx = 0; idx !== examples.length; ++idx) {\012        yield new Value(examples[idx], undefined);\012    }\012    for (let idx = 0, rng = random(seed);; ++idx) {\012        yield tossNext(generator, rng, idx);\012    }\012}\012function lazyGenerate(generator, rng, idx) {\012    return () => generator.generate(new Random(rng), idx);\012}\012export function* lazyToss(generator, seed, random, examples) {\012    yield* safeMap(examples, (e) => () => new Value(e, undefined));\012    let idx = 0;\012    let rng = random(seed);\012    for (;;) {\012        rng = rng.jump \? rng.jump() : skipN(rng, 42);\012        yield lazyGenerate(generator, rng, idx++);\012    }\012}\012";
