    "'use strict';\012\012function emptyScalarPosition(offset, before, pos) {\012    if (before) {\012        pos \?\? (pos = before.length);\012        for (let i = pos - 1; i >= 0; --i) {\012            let st = before[i];\012            switch (st.type) {\012                case 'space':\012                case 'comment':\012                case 'newline':\012                    offset -= st.source.length;\012                    continue;\012            }\012            // Technically, an empty scalar is immediately after the last non-empty\012            // node, but it's more useful to place it after any whitespace.\012            st = before[++i];\012            while (st\?.type === 'space') {\012                offset += st.source.length;\012                st = before[++i];\012            }\012            break;\012        }\012    }\012    return offset;\012}\012\012exports.emptyScalarPosition = emptyScalarPosition;\012";
