    "/** @internal */\012export function reduce(b, f) {\012  return function (iterable) {\012    if (Array.isArray(iterable)) {\012      return iterable.reduce(f, b);\012    }\012    let result = b;\012    for (const n of iterable) {\012      result = f(result, n);\012    }\012    return result;\012  };\012}\012/** @internal */\012export function map(f) {\012  return function (iterable) {\012    if (Array.isArray(iterable)) {\012      return iterable.map(f);\012    }\012    return function* () {\012      for (const n of iterable) {\012        yield f(n);\012      }\012    }();\012  };\012}\012//# sourceMappingURL=Iterable.js.map";
