    "'use strict'\012\012const RedirectHandler = require('../handler/redirect-handler')\012\012function createRedirectInterceptor ({ maxRedirections: defaultMaxRedirections } = {}) {\012  return (dispatch) => {\012    return function Intercept (opts, handler) {\012      const { maxRedirections = defaultMaxRedirections, ...rest } = opts\012\012      if (maxRedirections == null || maxRedirections === 0) {\012        return dispatch(opts, handler)\012      }\012\012      const dispatchOpts = { ...rest } // Stop sub dispatcher from also redirecting.\012      const redirectHandler = new RedirectHandler(dispatch, maxRedirections, dispatchOpts, handler)\012      return dispatch(dispatchOpts, redirectHandler)\012    }\012  }\012}\012\012module.exports = createRedirectInterceptor\012";
